import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test16_executable';
export function run(args) {
  const r = spawnSync(EXE, args, { encoding: 'latin1' });
  return { argv: args, stdout: r.stdout, stderr: r.stderr, code: r.status };
}
export function show(args, label='') {
  const r = run(args);
  const kb = args.includes('--key') ? Buffer.from(args[args.indexOf('--key')+1] ?? '', 'utf8').length : null;
  const db = args.includes('--data') ? Buffer.from(args[args.indexOf('--data')+1] ?? '', 'utf8').length : null;
  console.log('### ' + (label||'') + ` keyBytes=${kb} dataBytes=${db}`);
  console.log('ARGV   ' + JSON.stringify(args));
  console.log('CODE   ' + r.code);
  console.log('STDOUT ' + JSON.stringify(r.stdout));
  if (r.stderr) console.log('STDERR ' + JSON.stringify(r.stderr));
  console.log('');
  return r;
}
EOF
